# area: paramspec_concatenate
# hypothesis: a Concatenate decorator that injects a leading argument removes it from the wrapper signature, so wrong types for the remaining parameters are rejected.
from collections.abc import Callable
from typing import Concatenate, ParamSpec, TypeVar, reveal_type

P = ParamSpec('P')
R = TypeVar('R')


def with_logger(func: Callable[Concatenate[str, P], R]) -> Callable[P, R]:
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        return func('log', *args, **kwargs)

    return wrapper


@with_logger
def greet(logger: str, name: str, times: int = 1) -> str:
    return (logger + ' ' + name) * times


reveal_type(greet)  # (name: str, times: int = 1) -> str
print(greet('ann', times=2))


def probe() -> None:
    try:
        greet(3)  # expect-error: int is not str
    except TypeError:
        print('rejected at runtime')
    try:
        greet('ann', times='2')  # expect-error: str is not int
    except TypeError:
        print('rejected at runtime')


probe()
